function renderOverlay(){if(!state.naverMap||state.mapMode!=="admin")return;const svg=$("area-map"),size=state.naverMap.getSize(),projection=state.naverMap.getProjection();svg.setAttribute("viewBox",`0 0 ${size.width} ${size.height}`);svg.innerHTML=state.boundaries.map(({area,rings})=>`<path class="district ${state.areaId===area.id?"selected":""}" data-boundary="${area.id}" d="${rings.map((ring)=>ring.map(([lng,lat],i)=>{const p=projection.fromCoordToOffset(new naver.maps.LatLng(lat,lng));return `${i?"L":"M"}${p.x.toFixed(1)} ${p.y.toFixed(1)}`;}).join(" ")+" Z").join(" ")}" fill="${scoreColor(area)}" fill-opacity=".64" stroke="#235c43" stroke-width="${state.areaId===area.id?4:2}"></path>`).join("");document.querySelectorAll("[data-boundary]").forEach((path)=>path.addEventListener("click",()=>{state.areaId=path.dataset.boundary;render();}));}
function scheduleOverlay(){if(!state.naverMap||state.overlayFrame)return;state.overlayFrame=requestAnimationFrame(()=>{state.overlayFrame=null;renderOverlay();});}
function renderMarkers(){state.markers.forEach((marker)=>marker.setMap(null));state.markers=[];state.densityCircles.forEach((circle)=>circle.setMap(null));state.densityCircles=[];state.resultOriginMarker?.setMap(null);state.resultOriginCircle?.setMap(null);state.resultOriginMarker=null;state.resultOriginCircle=null;if(!state.naverMap||state.mapMode!=="facility")return;const data=state.data.facilities.filter((item)=>state.selected.has(item.category)&&(state.areaId?item.area_id===state.areaId:true)),standard=data.filter((item)=>!item.density_only),perCategory={};standard.forEach((item)=>{(perCategory[item.category]??=[]).push(item);});Object.values(perCategory).flatMap((items)=>items.slice(0,32)).forEach((item)=>{const m=CATEGORY_META[item.category],marker=new naver.maps.Marker({map:state.naverMap,position:new naver.maps.LatLng(item.lat,item.lng),title:item.name,icon:{content:`<span class="facility-dot" style="--dot-color:${m.color}"></span>`,size:new naver.maps.Size(12,12),anchor:new naver.maps.Point(6,6)}});naver.maps.Event.addListener(marker,"click",()=>{state.areaId=item.area_id;render();});state.markers.push(marker);});["cctv","security_light"].forEach((category)=>{if(!state.selected.has(category))return;areas().filter((area)=>!state.areaId||area.id===state.areaId).forEach((area)=>{const count=area.counts[category]||0;if(!count)return;state.densityCircles.push(new naver.maps.Circle({map:state.naverMap,center:new naver.maps.LatLng(...area.center),radius:120+Math.min(600,Math.sqrt(count)*8),fillColor:CATEGORY_META[category].color,fillOpacity:.18,strokeColor:CATEGORY_META[category].color,strokeOpacity:.75,strokeWeight:2}));});});}
function renderMap(){document.querySelectorAll("[data-map-mode]").forEach((button)=>button.classList.toggle("active",button.dataset.mapMode===state.mapMode));if(!state.naverMap)return;$("area-map").classList.toggle("is-hidden",state.mapMode!=="admin");if(state.mapMode==="admin")renderOverlay();else $("area-map").innerHTML="";renderMarkers();$("map-footnote").textContent=state.mapMode==="admin"?"색이 진할수록 선택 조건을 더 많이 충족합니다. 구역을 누르면 해당 동네가 선택됩니다.":"선택한 생활 조건과 동네에 해당하는 등록 시설을 표시합니다.";}
