function showRoute(route){if(!state.naverMap||!window.naver?.maps?.Polyline)return;state.routeLine?.setMap(null);const path=route.coordinates.map(([lng,lat])=>new naver.maps.LatLng(lat,lng));state.routeLine=new naver.maps.Polyline({map:state.naverMap,path,strokeColor:"#ef6e4d",strokeWeight:5,strokeOpacity:.9});const bounds=new naver.maps.LatLngBounds();path.forEach((point)=>bounds.extend(point));state.naverMap.fitBounds(bounds);}
