let sidebarFrame=0;
function updateFloatingSidebar(){if(sidebarFrame)return;sidebarFrame=requestAnimationFrame(()=>{sidebarFrame=0;const sidebar=document.querySelector(".preference-sidebar"),layout=document.querySelector(".preference-layout");if(!sidebar||!layout)return;const active=state.page==="map"&&state.recommendationStep===1&&window.innerWidth>1050&&layout.getBoundingClientRect().top<=94;sidebar.classList.toggle("is-floating",active);});}
function renderAddressCategories(){TRANSPORT_CATEGORY_IDS.forEach((id)=>state.addressSelected.delete(id));const totals={};state.data.facilities.forEach((item)=>{if(!TRANSPORT_CATEGORY_IDS.has(item.category))totals[item.category]=(totals[item.category]||0)+1;});const categories=state.data.categories.filter((item)=>!TRANSPORT_CATEGORY_IDS.has(item.id)&&totals[item.id]&&!item.density_only),groups=GROUP_ORDER.map((id)=>({id,label:GROUP_LABELS[id],items:categories.filter((item)=>categoryGroup(item)===id)})).filter((group)=>group.items.length);$("address-category-list").innerHTML=groups.map((group)=>`<section class="address-filter-group" style="--group-color:${GROUP_META[group.id]?.color||"#247a59"}"><header><span>${GROUP_META[group.id]?.icon||"✦"}</span><strong>${group.label}</strong><small>${group.items.length}개 항목</small></header><div>${group.items.map((item)=>{const meta=CATEGORY_META[item.id],active=state.addressSelected.has(item.id);return `<button class="${active?"active":""}" data-address-category="${item.id}" type="button" aria-pressed="${active}"><span>${meta.icon}</span><b>${item.label}</b><i>${active?"✓":"＋"}</i></button>`;}).join("")}</div></section>`).join("");document.querySelectorAll("[data-address-category]").forEach((button)=>button.addEventListener("click",()=>{const id=button.dataset.addressCategory;state.addressVisibleCount[id]=3;if(state.addressSelected.has(id))state.addressSelected.delete(id);else state.addressSelected.add(id);renderAddressCategories();renderAddressResults();}));}
function transportMarkup(compact=false){if(state.transportLoading)return '<div class="transport-state loading">주변 교통정보를 확인하고 있습니다…</div>';if(state.transportError)return `<div class="transport-state error">${escapeHtml(state.transportError)}</div>`;const payload=state.transport;if(!payload)return "";const items=payload.items||[];const buckets=TRANSPORT_BUCKETS.map((bucket)=>{const matches=items.filter((item)=>item.bucket===bucket.id);return `<section class="transport-bucket ${bucket.tone}"><header><span>${bucket.label}</span><b>${matches.length}곳</b></header><div>${matches.slice(0,compact?2:4).map((item)=>{const meta=CATEGORY_META[item.type]||CATEGORY_META.bus;const content=`<span>${meta.icon}</span><div><strong>${escapeHtml(item.name)}</strong><small>도보 약 ${item.walk_minutes}분 · ${Number(item.distance_m).toLocaleString("ko-KR")}m</small></div>`;return item.place_url?`<a href="${escapeHtml(item.place_url)}" target="_blank" rel="noreferrer">${content}<b>↗</b></a>`:`<article>${content}</article>`;}).join("")||'<p>조회된 교통시설이 없습니다.</p>'}</div></section>`;}).join("");return `<div class="transport-buckets">${buckets}</div><p class="transport-notice">${escapeHtml(payload.method||"")} ${escapeHtml(payload.warning||"")}</p>`;}
function addressSubwayMarkup(){if(state.transportLoading)return '<div class="transport-state loading">주변 지하철역을 확인하고 있습니다…</div>';if(state.transportError)return `<div class="transport-state error">${escapeHtml(state.transportError)}</div>`;if(!state.transport)return "";const items=selectedSubways();return `<div class="address-subway-summary"><span>🚇 ${walkRangeLabel()}</span><strong>${items.length}개 역</strong></div><div class="address-subway-list">${items.slice(0,6).map((item)=>{const content=`<span>🚇</span><div><strong>${escapeHtml(item.name)}</strong><small>도보 약 ${estimatedWalkMinutes(item.distance_m)}분 · ${Number(item.distance_m).toLocaleString("ko-KR")}m</small></div>`;return item.place_url?`<a href="${escapeHtml(item.place_url)}" target="_blank" rel="noreferrer">${content}<b>↗</b></a>`:`<article>${content}</article>`;}).join("")||'<p>선택한 도보 범위에 조회된 지하철역이 없습니다.</p>'}</div><p class="transport-notice">지도 좌표 간 거리와 분당 67m 보행 속도로 도보시간을 추정합니다.</p>`;}
function renderTransportAccess(){const visible=Boolean(state.origin),result=$("result-transport"),address=$("address-transport");result.hidden=true;address.hidden=!visible;if(visible)$("address-transport-content").innerHTML=addressSubwayMarkup();const report=$("report-transport-content");if(report)report.innerHTML="";}
async function loadTransport(){if(!state.origin)return;state.transport=null;state.transportError=null;state.transportLoading=true;renderTransportAccess();try{const response=await fetch(`/api/transport?lat=${encodeURIComponent(state.origin.lat)}&lng=${encodeURIComponent(state.origin.lng)}`,kakaoRequestOptions()),payload=await response.json();if(!response.ok)throw new Error(payload.detail||"지하철 정보를 불러오지 못했습니다.");state.transport=payload;}catch(error){state.transportError=error.message;}finally{state.transportLoading=false;renderTransportAccess();renderAddressMap();}}
function openPostcode(context="address"){if(!window.daum?.Postcode){state.addressError="주소 검색 서비스를 불러오지 못했습니다. 인터넷 연결을 확인해 주세요.";render();return;}new daum.Postcode({oncomplete:(data)=>{const address=data.userSelectedType==="R"?data.roadAddress:data.jibunAddress;if(!address){state.addressError="선택한 항목에서 주소를 확인하지 못했습니다.";render();return;}state.addressVisibleCount={};const input=$(context==="result"?"result-address-input":"address-input");input.value=address;analyzeAddress(address,context);}}).open();}
function clearAddressMap(){state.addressMarkers.forEach((marker)=>marker.setMap(null));state.addressMarkers=[];state.addressCircle?.setMap(null);state.addressCircle=null;}
function renderAddressMap(){if(!state.addressMap||!state.origin)return;$("address-map-placeholder").hidden=true;clearAddressMap();const center=new naver.maps.LatLng(state.origin.lat,state.origin.lng),boundaryRadius=state.addressMinutes===21?WALK_RADIUS[20]:WALK_RADIUS[state.addressMinutes];state.addressMap.setCenter(center);state.addressMap.setZoom(state.addressMinutes===10?14:state.addressMinutes===20?13:12);state.addressCircle=new naver.maps.Circle({map:state.addressMap,center,radius:boundaryRadius,fillColor:"#38a169",fillOpacity:state.addressMinutes===21?.02:.08,strokeColor:"#176b4d",strokeOpacity:.75,strokeWeight:2,strokeStyle:state.addressMinutes===21?"shortdash":"solid"});state.addressMarkers.push(new naver.maps.Marker({map:state.addressMap,position:center,title:"기준 주소",icon:{content:'<span class="address-origin-pin">기준</span>',size:new naver.maps.Size(38,38),anchor:new naver.maps.Point(19,19)}}));addressMarkerGroups(addressFacilitiesInRange()).forEach((items)=>{const lat=items.reduce((sum,item)=>sum+item.lat,0)/items.length,lng=items.reduce((sum,item)=>sum+item.lng,0)/items.length,position=new naver.maps.LatLng(lat,lng);if(items.length===1){const item=items[0],meta=CATEGORY_META[item.category];state.addressMarkers.push(new naver.maps.Marker({map:state.addressMap,position,title:`${item.name} · 도보 약 ${estimatedWalkMinutes(item.distance_m)}분`,icon:{content:`<span class="facility-dot" style="--dot-color:${meta.color}"></span>`,size:new naver.maps.Size(12,12),anchor:new naver.maps.Point(6,6)}}));return;}const marker=new naver.maps.Marker({map:state.addressMap,position,title:`주변 시설 ${items.length}곳`,icon:{content:`<button class="facility-cluster" type="button" aria-label="주변 시설 ${items.length}곳">${items.length}</button>`,size:new naver.maps.Size(38,38),anchor:new naver.maps.Point(19,19)}});naver.maps.Event.addListener(marker,"click",()=>{state.addressMap.panTo(position);state.addressMap.setZoom(Math.min(18,state.addressMap.getZoom()+2),true);});state.addressMarkers.push(marker);});selectedSubways().forEach((item)=>{state.addressMarkers.push(new naver.maps.Marker({map:state.addressMap,position:new naver.maps.LatLng(item.lat,item.lng),title:`${item.name} · 도보 약 ${estimatedWalkMinutes(item.distance_m)}분`,icon:{content:'<span class="subway-map-marker">🚇</span>',size:new naver.maps.Size(30,30),anchor:new naver.maps.Point(15,15)}}));});}
async function ensureAddressMap(){if(state.addressMap||!state.naverKey)return;if(!state.origin)return;try{await loadNaverMaps(state.naverKey);state.addressMap=new naver.maps.Map("address-naver-map",{center:new naver.maps.LatLng(state.origin.lat,state.origin.lng),zoom:14,zoomControl:true,mapDataControl:false,scaleControl:false});$("address-map-placeholder").hidden=true;renderAddressMap();}catch{$("address-map-placeholder").textContent="네이버 지도를 불러오지 못했습니다.";}}
function renderAddressStatus(){document.querySelectorAll("#address-walk-segment button").forEach((button)=>button.classList.toggle("active",Number(button.dataset.minutes)===state.addressMinutes));const status=$("address-status");if(state.addressError){status.className="error";status.innerHTML=`<strong>주소를 확인하지 못했습니다.</strong><span>${escapeHtml(state.addressError)}</span>`;return;}if(!state.origin){status.className="";status.textContent="주소 찾기에서 시흥시 내 정확한 주소를 선택해 주세요.";return;}const count=nearbyFacilities().length,subways=selectedSubways().length;status.className=state.addressSelected.size?"success":"";status.innerHTML=state.addressSelected.size?`<strong>✓ ${escapeHtml(state.origin.address)}</strong><span>${walkRangeLabel()} · ${walkRangeDetail()} · 선택 시설 ${count.toLocaleString("ko-KR")}곳 · 지하철역 ${subways}곳</span>`:`<strong>✓ ${escapeHtml(state.origin.address)}</strong><span>${walkRangeLabel()} 지하철 접근성을 조회했습니다. 생활시설도 보려면 시설 유형을 선택해 주세요.</span>`;}
function renderResultWalkStatus(){document.querySelectorAll("#result-walk-segment button").forEach((button)=>button.classList.toggle("active",Number(button.dataset.minutes)===state.addressMinutes));const status=$("result-walk-status");if(state.addressError){status.className="result-walk-status error";status.innerHTML=`<strong>주소를 확인하지 못했습니다.</strong> ${escapeHtml(state.addressError)}`;return;}if(!state.origin){status.className="result-walk-status";status.textContent="주소를 선택하면 지도와 종합 리포트에 생활권 결과가 추가됩니다.";return;}const facilities=recommendationNearbyFacilities(),area=state.origin.areaId?areaById(state.origin.areaId):null;status.className="result-walk-status success";status.innerHTML=`<div><strong>✓ ${escapeHtml(state.origin.address)}</strong><span>${area?`${area.name} · `:""}도보 ${state.addressMinutes}분 · 선택 조건 시설 ${facilities.length.toLocaleString("ko-KR")}곳과 주변 교통을 확인했습니다.</span></div><button data-result-walk-clear type="button">주소 조회 지우기</button>`;status.querySelector("[data-result-walk-clear]").addEventListener("click",()=>{state.origin=null;state.addressError=null;state.transport=null;state.transportError=null;state.mapMode="admin";$("result-address-input").value="";$("address-input").value="";render();});}
function renderAddressResults(){renderAddressStatus();const summary=$("address-life-summary");if(!state.origin){clearAddressMap();summary.hidden=true;$("address-map-placeholder").hidden=false;$("address-map-placeholder").textContent="주소를 분석하면 이곳에 생활권 지도가 표시됩니다.";$("address-result-title").textContent="분석 결과";$("address-result-count").textContent="분석 전";$("address-facility-list").innerHTML='<div class="ranking-empty"><span>⌖</span><strong>아직 분석한 주소가 없습니다</strong><p>주소 찾기에서 정확한 주소를 선택한 후 분석을 진행해 주세요.</p></div>';return;}const facilities=addressFacilitiesInRange(),subways=selectedSubways(),selectedCategories=state.data.categories.filter((category)=>state.addressSelected.has(category.id)),groups=GROUP_ORDER.map((id)=>({id,label:GROUP_LABELS[id],categories:selectedCategories.map((category)=>({...category,items:sortedAddressFacilities(facilities.filter((item)=>item.category===category.id))})).filter((category)=>categoryGroup(category)===id&&category.items.length)})).filter((group)=>group.categories.length),groupCounts=groups.map((group)=>({id:group.id,label:group.label,count:group.categories.reduce((sum,category)=>sum+category.items.length,0)}));$("address-result-title").textContent=`${walkRangeLabel()} 생활권`;$("address-result-count").textContent=`시설 ${facilities.length.toLocaleString("ko-KR")}곳 · 역 ${subways.length}곳`;summary.hidden=false;summary.innerHTML=`<div class="address-summary-head"><div><small>LIFE AREA SUMMARY</small><strong>생활권 요약</strong></div><b>총 ${(facilities.length+subways.length).toLocaleString("ko-KR")}곳</b></div><div class="address-summary-chips">${groupCounts.map((group)=>`<button data-address-summary-group="${group.id}" type="button"><span>${GROUP_META[group.id]?.icon||"✦"}</span>${group.label}<b>${group.count.toLocaleString("ko-KR")}</b></button>`).join("")}${subways.length?`<button data-address-transport-jump type="button"><span>🚇</span>교통<b>${subways.length}</b></button>`:""}</div>`;$("address-facility-list").innerHTML=groups.length?`<div class="address-list-heading"><div><small>SELECTED PLACES</small><strong>선택한 시설</strong></div><label>정렬<select id="address-result-sort"><option value="distance" ${state.addressSort==="distance"?"selected":""}>가까운 순</option><option value="name" ${state.addressSort==="name"?"selected":""}>이름순</option></select></label></div>${groups.map((group)=>`<section class="address-result-group" id="address-group-${group.id}" style="--group-color:${GROUP_META[group.id]?.color||"#247a59"}"><header><span>${GROUP_META[group.id]?.icon||"✦"}</span><strong>${group.label}</strong><small>${group.categories.reduce((sum,category)=>sum+category.items.length,0)}곳</small></header><div class="address-result-categories">${group.categories.map((category)=>{const meta=CATEGORY_META[category.id],visible=Math.min(category.items.length,state.addressVisibleCount[category.id]||3),items=category.items.slice(0,visible),remaining=category.items.length-visible;return `<article class="address-result-category"><div class="address-result-category-head"><span>${meta.icon}</span><strong>${category.label}</strong><small>${category.items.length}곳</small></div><div>${items.map((item,index)=>`<a class="address-facility-card" href="${escapeHtml(kakaoPlaceLink(item))}" target="_blank" rel="noreferrer"><em>${index+1}</em><span style="--facility-color:${meta.color}">${meta.icon}</span><div><small>도보 약 ${estimatedWalkMinutes(item.distance_m)}분 · ${item.distance_m.toLocaleString("ko-KR")}m</small><strong>${escapeHtml(item.name)}</strong><p>${escapeHtml(item.address)}</p></div><b>카카오맵 ↗</b></a>`).join("")}</div>${category.items.length>3?`<div class="address-more-row"><button data-address-more="${category.id}" type="button">${remaining?`${remaining.toLocaleString("ko-KR")}곳 더보기`:`접기`}<span>${remaining?"＋":"↑"}</span></button></div>`:""}</article>`;}).join("")}</div></section>`).join("")}`:'<div class="ranking-empty"><span>0</span><strong>선택한 시설이 없습니다</strong><p>왼쪽에서 확인할 생활시설을 선택해 주세요.</p></div>';document.querySelectorAll("[data-address-summary-group]").forEach((button)=>button.addEventListener("click",()=>document.getElementById(`address-group-${button.dataset.addressSummaryGroup}`)?.scrollIntoView({behavior:"smooth",block:"start"})));document.querySelector("[data-address-transport-jump]")?.addEventListener("click",()=>$("address-transport").scrollIntoView({behavior:"smooth",block:"center"}));$("address-result-sort")?.addEventListener("change",(event)=>{state.addressSort=event.target.value;renderAddressResults();});document.querySelectorAll("[data-address-more]").forEach((button)=>button.addEventListener("click",()=>{const id=button.dataset.addressMore,total=facilities.filter((item)=>item.category===id).length,current=state.addressVisibleCount[id]||3;state.addressVisibleCount[id]=current>=total?3:Math.min(total,current+10);renderAddressResults();document.querySelector(`[data-address-more="${id}"]`)?.scrollIntoView({behavior:"smooth",block:"nearest"});}));renderTransportAccess();if(state.addressMap)renderAddressMap();else if(!state.naverKey)$("address-map-placeholder").textContent="네이버 지도 API를 연결하면 주소 중심의 생활권 지도가 표시됩니다.";}
async function analyzeAddress(address,context="address"){const value=address.trim(),input=$(context==="result"?"result-address-input":"address-input");if(!value){state.origin=null;state.addressError="주소 찾기에서 정확한 주소를 선택해 주세요.";render();input.focus();return;}state.origin=null;state.transport=null;state.transportError=null;state.addressError=null;$("address-status").className="loading";$("address-status").textContent="선택한 주소의 좌표를 확인하고 있습니다…";$("result-walk-status").className="result-walk-status loading";$("result-walk-status").textContent="선택한 주소의 좌표를 확인하고 있습니다…";try{const response=await fetch(`/api/geocode?address=${encodeURIComponent(value)}`,kakaoRequestOptions()),payload=await response.json();if(!response.ok)throw new Error(payload.detail||"주소를 찾지 못했습니다.");state.origin={address:payload.address,lat:Number(payload.lat),lng:Number(payload.lng),areaId:payload.area_id||null,source:payload.source};state.addressError=null;$("address-input").value=payload.address;$("result-address-input").value=payload.address;render();await Promise.all([ensureAddressMap(),loadTransport()]);renderAddressMap();}catch(error){state.origin=null;state.transport=null;state.addressError=error.message;render();}}
function resetRecommendation(){state.selected.clear();state.priority=[];state.areaId=null;state.activeGroup=state.data.groups?.[0]?.id||"daily";render();}
function bindKakaoKeyForm(){const form=$("kakao-key-form"),input=$("kakao-rest-key-input"),status=$("kakao-key-status");if(!form)return;status.textContent=state.serverKakaoReady?"서버에 연결됨":"연결되지 않음";form.addEventListener("submit",(event)=>{event.preventDefault();const key=input.value.trim();state.kakaoRestKey=key;status.textContent=key?"현재 브라우저에서 연결됨":state.serverKakaoReady?"서버에 연결됨":"연결되지 않음";input.value="";});}
function renderRecommendationStep(){const ids=selectedPriority(),isResults=state.recommendationStep===2,ready=ids.length>0;$("recommendation-step-1").hidden=isResults;$("recommendation-step-1").classList.toggle("active",!isResults);$("recommendation-step-2").hidden=!isResults;$("recommendation-step-2").classList.toggle("active",isResults);document.querySelectorAll("[data-progress-step]").forEach((item)=>{const step=Number(item.dataset.progressStep);item.classList.toggle("active",step===state.recommendationStep);item.classList.toggle("complete",step<state.recommendationStep);});const next=$("show-results");next.disabled=!ready;next.querySelector("span").textContent=ready?`${ids.length}개 조건으로 추천 결과 보기`:"생활 조건을 먼저 선택해 주세요";$("result-summary-copy").textContent=ready?`${ids.map((id)=>CATEGORY_META[id].label).join(" · ")} 조건의 등록 시설 수를 같은 비중으로 비교했습니다.`:"선택한 생활 조건을 기준으로 시흥의 동네를 비교했습니다.";}
async function goToRecommendationStep(step){if(step===2&&!state.selected.size)return;state.recommendationStep=step;if(step===2){state.areaId=null;state.mapMode="admin";state.origin=null;state.addressError=null;state.transport=null;state.transportError=null;render();await ensureMap();requestAnimationFrame(()=>{state.naverMap?.autoResize();renderMap();window.scrollTo({top:0,behavior:"smooth"});});}else{renderRecommendationStep();window.scrollTo({top:0,behavior:"smooth"});}}
function closeNeighborhoodMenu(){const button=$("neighborhood-menu-button"),menu=$("neighborhood-menu");if(!button||!menu)return;button.setAttribute("aria-expanded","false");menu.hidden=true;}
function updateNeighborhoodNavState(){const button=$("neighborhood-menu-button");if(!button)return;button.classList.toggle("active",["map","address","detail"].includes(state.page));document.querySelectorAll("#neighborhood-menu [data-page-link]").forEach((link)=>{const active=link.dataset.pageLink==="address"?state.page==="address":["map","detail"].includes(state.page);link.classList.toggle("active",active);});}
function bindNeighborhoodMenu(){const button=$("neighborhood-menu-button"),menu=$("neighborhood-menu"),wrapper=button?.closest(".neighborhood-nav");if(!button||!menu||!wrapper)return;button.addEventListener("click",(event)=>{event.stopPropagation();const open=button.getAttribute("aria-expanded")!=="true";button.setAttribute("aria-expanded",String(open));menu.hidden=!open;});document.addEventListener("click",(event)=>{if(!wrapper.contains(event.target))closeNeighborhoodMenu();});document.addEventListener("keydown",(event)=>{if(event.key==="Escape"){closeNeighborhoodMenu();button.focus();}});updateNeighborhoodNavState();}
function showPage(page,hash=true){let next=["home","map","address","detail","running","about"].includes(page)?page:"home";if(next==="detail"&&!state.areaId){next="map";state.recommendationStep=state.selected.size?2:1;}state.page=next;document.querySelectorAll(".app-page").forEach((item)=>{const active=item.dataset.page===next;item.hidden=!active;item.classList.toggle("active",active);});document.querySelectorAll(".topbar nav [data-page-link]").forEach((link)=>link.classList.toggle("active",link.dataset.pageLink===next));document.querySelector(".header-cta").hidden=next!=="home";document.querySelector(".topbar").classList.remove("menu-open");$("mobile-menu").setAttribute("aria-expanded","false");closeNeighborhoodMenu();updateNeighborhoodNavState();if(hash&&location.hash!==`#${next}`)history.pushState(null,"",`#${next}`);window.scrollTo({top:0,behavior:"smooth"});if(next==="map"&&state.recommendationStep===2)requestAnimationFrame(async()=>{await ensureMap();state.naverMap?.autoResize();renderMap();});if(next==="address")requestAnimationFrame(async()=>{await ensureAddressMap();state.addressMap?.autoResize();renderAddressMap();});}
let addressResultsObserver=null;
function installAddressCollapseButtons(){document.querySelectorAll(".address-more-row [data-address-more]").forEach((moreButton)=>{const id=moreButton.dataset.addressMore,current=state.addressVisibleCount[id]||3;if(current<=3||moreButton.textContent.includes("접기")||moreButton.parentElement.querySelector("[data-address-collapse]"))return;const collapse=document.createElement("button");collapse.type="button";collapse.className="address-collapse-button";collapse.dataset.addressCollapse=id;collapse.innerHTML="접기 <span>↑</span>";collapse.addEventListener("click",()=>{state.addressVisibleCount[id]=3;renderAddressResults();});moreButton.insertAdjacentElement("afterend",collapse);});}
function observeAddressResults(){if(addressResultsObserver)return;const target=$("address-facility-list");if(!target)return;addressResultsObserver=new MutationObserver(installAddressCollapseButtons);addressResultsObserver.observe(target,{childList:true,subtree:true});installAddressCollapseButtons();}
function render(){syncPriority();renderCategories();renderSelectionSummary();renderRanking();renderMapSelection();renderDetail();renderReportFacilities();renderMap();renderRoutes();renderRecommendationStep();renderBudget();renderAddressCategories();renderAddressResults();observeAddressResults();renderResultWalkStatus();renderTransportAccess();}
function bindControls(){document.querySelectorAll("[data-page-link]").forEach((link)=>link.addEventListener("click",(event)=>{event.preventDefault();showPage(link.dataset.pageLink);}));$("mobile-menu").addEventListener("click",()=>{const open=document.querySelector(".topbar").classList.toggle("menu-open");$("mobile-menu").setAttribute("aria-expanded",String(open));});window.addEventListener("popstate",()=>showPage(location.hash.slice(1),false));$("address-form").addEventListener("submit",(event)=>{event.preventDefault();openPostcode("address");});$("result-address-form").addEventListener("submit",(event)=>{event.preventDefault();openPostcode("result");});$("address-filter-reset").addEventListener("click",()=>{state.addressSelected.clear();state.addressVisibleCount={};renderAddressCategories();renderAddressResults();});document.querySelectorAll("#address-walk-segment button,#result-walk-segment button").forEach((button)=>button.addEventListener("click",()=>{state.addressMinutes=Number(button.dataset.minutes);state.addressVisibleCount={};render();renderAddressMap();renderMap();}));$("reset-selection").addEventListener("click",resetRecommendation);$("summary-reset").addEventListener("click",resetRecommendation);document.querySelectorAll("[data-housing-type]").forEach((button)=>button.addEventListener("click",()=>{const presets={monthly:{primary:[30,100],deposit:[500,5000]},jeonse:{deposit:[10000,40000]},sale:{primary:[20000,80000]}},preset=presets[button.dataset.housingType];state.housingType=button.dataset.housingType;if(preset.primary)[state.budgetMin,state.budgetMax]=preset.primary;if(preset.deposit)[state.depositMin,state.depositMax]=preset.deposit;renderBudget();}));[["budget-min","budgetMin","budgetMax"],["budget-max","budgetMax","budgetMin"],["budget-min-input","budgetMin","budgetMax"],["budget-max-input","budgetMax","budgetMin"],["deposit-min","depositMin","depositMax"],["deposit-max","depositMax","depositMin"],["deposit-min-input","depositMin","depositMax"],["deposit-max-input","depositMax","depositMin"]].forEach(([id,key,otherKey])=>$(id).addEventListener(id.includes("input")?"change":"input",(event)=>{const maximum=Number(event.target.max),value=Math.min(maximum,Math.max(0,Number(event.target.value)||0));state[key]=value;const isMinimum=key.endsWith("Min");if(isMinimum&&state[key]>state[otherKey])state[otherKey]=state[key];if(!isMinimum&&state[key]<state[otherKey])state[otherKey]=state[key];renderBudget();}));$("show-results").addEventListener("click",()=>goToRecommendationStep(2));$("back-to-conditions").addEventListener("click",()=>goToRecommendationStep(1));$("criteria-button").addEventListener("click",()=>$("criteria-dialog").showModal());document.querySelector(".dialog-close").addEventListener("click",()=>$("criteria-dialog").close());$("show-facilities-on-map").addEventListener("click",()=>{state.recommendationStep=2;showPage("map");renderRecommendationStep();});$("map-zoom-in").addEventListener("click",()=>state.naverMap?.setZoom(state.naverMap.getZoom()+1,true));$("map-zoom-out").addEventListener("click",()=>state.naverMap?.setZoom(state.naverMap.getZoom()-1,true));$("map-fullscreen").addEventListener("click",()=>document.querySelector(".map-canvas").requestFullscreen());document.querySelectorAll("[data-map-mode]").forEach((button)=>button.addEventListener("click",()=>{state.mapMode=button.dataset.mapMode;document.querySelectorAll("[data-map-mode]").forEach((item)=>item.classList.toggle("active",item===button));renderMap();}));$("route-dialog-close").addEventListener("click",()=>$("route-dialog").close());$("route-dialog").addEventListener("click",(event)=>{if(event.target===$("route-dialog"))$("route-dialog").close();});}
async function init(){try{const response=await fetch("/api/infrastructure");if(!response.ok)throw new Error("생활 인프라 데이터를 불러오지 못했습니다.");state.data=await response.json();const received=new Map(state.data.categories.map((category)=>[category.id,category]));state.data.categories=FINAL_CATEGORIES.map((category)=>({...received.get(category.id),...category}));state.data.categories.forEach((category)=>{const group=GROUP_META[categoryGroup(category)]||GROUP_META.daily;CATEGORY_META[category.id]={...group,...CATEGORY_META[category.id],label:category.label,icon:CATEGORY_ICONS[category.id]||CATEGORY_META[category.id]?.icon||group.icon,color:CATEGORY_META[category.id]?.color||group.color,density_only:Boolean(category.density_only)};});const [housingResponse,configResponse]=await Promise.all([fetch("/api/housing-costs"),fetch("/api/config")]);if(housingResponse.ok)state.housingData=await housingResponse.json();const config=await configResponse.json();state.naverKey=config.naver_maps_key_id||"";state.serverKakaoReady=Boolean(config.kakao_rest_ready);await loadBoundaries();bindControls();bindKakaoKeyForm();window.addEventListener("scroll",updateFloatingSidebar,{passive:true});window.addEventListener("resize",updateFloatingSidebar,{passive:true});render();showPage(location.hash.slice(1)||"home",false);updateFloatingSidebar();}catch(error){document.body.innerHTML=`<main class="fatal"><h1>서비스를 불러오지 못했습니다.</h1><p>${escapeHtml(error.message)}</p></main>`;}}
bindNeighborhoodMenu();
init();
